/**
 * Tokenizer module for converting various input types to standardized string tokens.
 *
 * This module demonstrates Scala's type system with:
 * - Sealed traits and enums for type safety
 * - Generics with variance annotations
 * - Option/Either for error handling
 * - Type classes for ad-hoc polymorphism
 * - Immutable data structures with case classes
 */

import java.time.{LocalDate, LocalDateTime}
import java.time.format.DateTimeFormatter
import scala.util.{Try, Success, Failure}
import scala.collection.mutable

// ============================================================================
// Enums and Constants
// ============================================================================

sealed trait TokenType {
  def value: String
}

object TokenType {
  case object String extends TokenType { val value = "string" }
  case object Numeric extends TokenType { val value = "numeric" }
  case object Temporal extends TokenType { val value = "temporal" }
  case object Structured extends TokenType { val value = "structured" }
  case object Binary extends TokenType { val value = "binary" }
  case object Null extends TokenType { val value = "null" }

  val values: Seq[TokenType] = Seq(String, Numeric, Temporal, Structured, Binary, Null)

  def fromString(s: String): Option[TokenType] = values.find(_.value == s)
}

// ============================================================================
// Type Classes for Structural Typing
// ============================================================================

/**
 * Type class for objects that can be converted to a token string.
 */
trait Tokenizable[A] {
  def toToken(a: A): String
}

object Tokenizable {
  def apply[A](implicit ev: Tokenizable[A]): Tokenizable[A] = ev

  implicit val stringTokenizable: Tokenizable[String] = (a: String) => a
  implicit val intTokenizable: Tokenizable[Int] = (a: Int) => a.toString
  implicit val longTokenizable: Tokenizable[Long] = (a: Long) => a.toString
  implicit val doubleTokenizable: Tokenizable[Double] = (a: Double) => a.toString
  implicit val bigDecimalTokenizable: Tokenizable[BigDecimal] = (a: BigDecimal) => a.toString()
}

/**
 * Type class for objects with a length.
 */
trait HasLength[A] {
  def length(a: A): Int
}

object HasLength {
  def apply[A](implicit ev: HasLength[A]): HasLength[A] = ev

  implicit val stringHasLength: HasLength[String] = (a: String) => a.length
  implicit def seqHasLength[T]: HasLength[Seq[T]] = (a: Seq[T]) => a.length
  implicit def arrayHasLength[T]: HasLength[Array[T]] = (a: Array[T]) => a.length
}

/**
 * Type class for token processors.
 */
trait TokenProcessor[-A] {
  def process(item: A): Unit
}

// ============================================================================
// Core Token Classes
// ============================================================================

/**
 * Immutable token representation.
 */
final case class Token(
    value: String,
    tokenType: TokenType,
    metadata: Map[String, Any] = Map.empty
) {

  /**
   * Return new token with additional metadata.
   */
  def withMetadata(entries: (String, Any)*): Token =
    copy(metadata = metadata ++ entries.toMap)
}

/**
 * Mutable batch of tokens - contrast with immutable Token.
 */
final class MutableTokenBatch private (
    private val _tokens: mutable.ListBuffer[Token],
    private var _processed: Boolean
) {

  def tokens: Seq[Token] = _tokens.toSeq

  def add(token: Token): Either[RuntimeException, Unit] =
    if (_processed) Left(new RuntimeException("Batch already processed"))
    else {
      _tokens += token
      Right(())
    }

  def markProcessed(): Unit = _processed = true

  def isProcessed: Boolean = _processed
}

object MutableTokenBatch {
  def apply(): MutableTokenBatch = new MutableTokenBatch(mutable.ListBuffer.empty, false)
}

// ============================================================================
// Generic Container Classes
// ============================================================================

/**
 * Covariant container - can return subtypes.
 */
final class TokenContainer[+A](items: Seq[A]) {
  private val _items: Vector[A] = items.toVector

  def getAll: Vector[A] = _items

  def mapTokens(func: A => String): Vector[String] = _items.map(func)
}

object TokenContainer {
  def apply[A](items: A*): TokenContainer[A] = new TokenContainer(items.toSeq)
}

/**
 * Contravariant sink - can accept supertypes.
 */
final class TokenSink[-A] {
  private val _received: mutable.ListBuffer[Any] = mutable.ListBuffer.empty

  def receive(item: A): Unit = _received += item

  def drain(): Seq[Any] = {
    val result = _received.toSeq
    _received.clear()
    result
  }
}

object TokenSink {
  def apply[A](): TokenSink[A] = new TokenSink[A]
}

/**
 * Invariant handler - exact type matching required.
 */
final class BivariantHandler[A](private var _value: A) {

  def get: A = _value

  def set(value: A): Unit = _value = value

  def transform(func: A => A): A = {
    _value = func(_value)
    _value
  }
}

object BivariantHandler {
  def apply[A](default: A): BivariantHandler[A] = new BivariantHandler(default)
}

// ============================================================================
// Tokenizer Implementations
// ============================================================================

/**
 * Abstract base tokenizer with generic input type.
 */
trait BaseTokenizer[A] {

  /**
   * Convert value to token.
   */
  def tokenize(value: A): Token

  /**
   * Lazy tokenization of multiple values.
   */
  def tokenizeBatch(values: Iterable[A]): Iterator[Token] =
    values.iterator.map(tokenize)
}

/**
 * Tokenizer for string and bytes types.
 */
final class StringTokenizer(
    encoding: String = "UTF-8",
    normalizer: String => String = identity
) extends BaseTokenizer[Either[String, Array[Byte]]] {

  override def tokenize(value: Either[String, Array[Byte]]): Token = {
    val strValue = value match {
      case Left(s)      => s
      case Right(bytes) => new String(bytes, encoding)
    }
    val normalized = normalizer(strValue)
    Token(normalized, TokenType.String)
  }

  /**
   * Convenience method for tokenizing strings directly.
   */
  def tokenizeString(value: String): Token =
    tokenize(Left(value))

  /**
   * Convenience method for tokenizing bytes directly.
   */
  def tokenizeBytes(value: Array[Byte]): Token =
    tokenize(Right(value))
}

object StringTokenizer {
  def apply(
      encoding: String = "UTF-8",
      normalizer: String => String = identity
  ): StringTokenizer = new StringTokenizer(encoding, normalizer)
}

/**
 * Sealed trait for numeric types supported by NumericTokenizer.
 */
sealed trait NumericValue {
  def originalTypeName: String
}

object NumericValue {
  final case class IntValue(value: Int) extends NumericValue {
    val originalTypeName = "Int"
  }
  final case class LongValue(value: Long) extends NumericValue {
    val originalTypeName = "Long"
  }
  final case class DoubleValue(value: Double) extends NumericValue {
    val originalTypeName = "Double"
  }
  final case class BigDecimalValue(value: BigDecimal) extends NumericValue {
    val originalTypeName = "BigDecimal"
  }

  implicit def fromInt(v: Int): NumericValue = IntValue(v)
  implicit def fromLong(v: Long): NumericValue = LongValue(v)
  implicit def fromDouble(v: Double): NumericValue = DoubleValue(v)
  implicit def fromBigDecimal(v: BigDecimal): NumericValue = BigDecimalValue(v)
}

/**
 * Tokenizer for numeric types with precision handling.
 */
final class NumericTokenizer(
    precision: Int = 6,
    formatOptions: Map[String, Any] = Map.empty
) extends BaseTokenizer[NumericValue] {

  override def tokenize(value: NumericValue): Token = {
    val strValue = value match {
      case NumericValue.IntValue(v)        => v.toString
      case NumericValue.LongValue(v)       => v.toString
      case NumericValue.DoubleValue(v)     => s"%.${precision}f".format(v)
      case NumericValue.BigDecimalValue(v) => v.setScale(precision, BigDecimal.RoundingMode.HALF_UP).toString()
    }
    Token(strValue, TokenType.Numeric, Map("original_type" -> value.originalTypeName))
  }
}

object NumericTokenizer {
  def apply(
      precision: Int = 6,
      formatOptions: Map[String, Any] = Map.empty
  ): NumericTokenizer = new NumericTokenizer(precision, formatOptions)
}

/**
 * Sealed trait for temporal types supported by TemporalTokenizer.
 */
sealed trait TemporalValue

object TemporalValue {
  final case class DateTimeValue(value: LocalDateTime) extends TemporalValue
  final case class DateValue(value: LocalDate) extends TemporalValue

  implicit def fromDateTime(v: LocalDateTime): TemporalValue = DateTimeValue(v)
  implicit def fromDate(v: LocalDate): TemporalValue = DateValue(v)
}

/**
 * Tokenizer for date/time types.
 */
final class TemporalTokenizer(formatStr: Option[String] = None) extends BaseTokenizer[TemporalValue] {

  private val isoFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd'T'HH:mm:ss")
  private val dateFormat: DateTimeFormatter = DateTimeFormatter.ofPattern("yyyy-MM-dd")

  override def tokenize(value: TemporalValue): Token = {
    val formatted = formatStr match {
      case Some(fmt) =>
        val formatter = DateTimeFormatter.ofPattern(fmt)
        value match {
          case TemporalValue.DateTimeValue(dt) => dt.format(formatter)
          case TemporalValue.DateValue(d)      => d.format(formatter)
        }
      case None =>
        value match {
          case TemporalValue.DateTimeValue(dt) => dt.format(isoFormat)
          case TemporalValue.DateValue(d)      => d.format(dateFormat)
        }
    }
    Token(formatted, TokenType.Temporal)
  }
}

object TemporalTokenizer {
  val IsoFormat: String = "yyyy-MM-dd'T'HH:mm:ss"
  val DateFormat: String = "yyyy-MM-dd"

  def apply(formatStr: Option[String] = None): TemporalTokenizer = new TemporalTokenizer(formatStr)
}

// ============================================================================
// Advanced: Union Types via Sealed Trait
// ============================================================================

/**
 * Sealed trait representing values that can be tokenized by UniversalTokenizer.
 */
sealed trait TokenizableValue

object TokenizableValue {
  final case class StringVal(value: String) extends TokenizableValue
  final case class BytesVal(value: Array[Byte]) extends TokenizableValue
  final case class IntVal(value: Int) extends TokenizableValue
  final case class LongVal(value: Long) extends TokenizableValue
  final case class DoubleVal(value: Double) extends TokenizableValue
  final case class BigDecimalVal(value: BigDecimal) extends TokenizableValue
  final case class DateTimeVal(value: LocalDateTime) extends TokenizableValue
  final case class DateVal(value: LocalDate) extends TokenizableValue
  final case class CustomVal[A](value: A)(implicit ev: Tokenizable[A]) extends TokenizableValue {
    def toTokenString: String = ev.toToken(value)
  }
  case object NullVal extends TokenizableValue

  implicit def fromString(v: String): TokenizableValue = StringVal(v)
  implicit def fromBytes(v: Array[Byte]): TokenizableValue = BytesVal(v)
  implicit def fromInt(v: Int): TokenizableValue = IntVal(v)
  implicit def fromLong(v: Long): TokenizableValue = LongVal(v)
  implicit def fromDouble(v: Double): TokenizableValue = DoubleVal(v)
  implicit def fromBigDecimal(v: BigDecimal): TokenizableValue = BigDecimalVal(v)
  implicit def fromDateTime(v: LocalDateTime): TokenizableValue = DateTimeVal(v)
  implicit def fromDate(v: LocalDate): TokenizableValue = DateVal(v)
  def fromNull: TokenizableValue = NullVal
}

/**
 * Tokenizer that handles multiple types with pattern matching.
 */
final class UniversalTokenizer {
  private val stringTokenizer = StringTokenizer()
  private val numericTokenizer = NumericTokenizer()
  private val temporalTokenizer = TemporalTokenizer()

  def tokenize(value: TokenizableValue): Token = value match {
    case TokenizableValue.NullVal =>
      Token("NULL", TokenType.Null)

    case TokenizableValue.CustomVal(_) =>
      val custom = value.asInstanceOf[TokenizableValue.CustomVal[_]]
      Token(custom.toTokenString, TokenType.Structured)

    case TokenizableValue.StringVal(s) =>
      stringTokenizer.tokenizeString(s)

    case TokenizableValue.BytesVal(b) =>
      stringTokenizer.tokenizeBytes(b)

    case TokenizableValue.IntVal(i) =>
      numericTokenizer.tokenize(NumericValue.IntValue(i))

    case TokenizableValue.LongVal(l) =>
      numericTokenizer.tokenize(NumericValue.LongValue(l))

    case TokenizableValue.DoubleVal(d) =>
      numericTokenizer.tokenize(NumericValue.DoubleValue(d))

    case TokenizableValue.BigDecimalVal(bd) =>
      numericTokenizer.tokenize(NumericValue.BigDecimalValue(bd))

    case TokenizableValue.DateTimeVal(dt) =>
      temporalTokenizer.tokenize(TemporalValue.DateTimeValue(dt))

    case TokenizableValue.DateVal(d) =>
      temporalTokenizer.tokenize(TemporalValue.DateValue(d))
  }

  /**
   * Tokenize any value with fallback to string conversion.
   */
  def tokenizeAny(value: Any): Token = value match {
    case null            => tokenize(TokenizableValue.NullVal)
    case s: String       => tokenize(TokenizableValue.StringVal(s))
    case b: Array[Byte]  => tokenize(TokenizableValue.BytesVal(b))
    case i: Int          => tokenize(TokenizableValue.IntVal(i))
    case l: Long         => tokenize(TokenizableValue.LongVal(l))
    case d: Double       => tokenize(TokenizableValue.DoubleVal(d))
    case bd: BigDecimal  => tokenize(TokenizableValue.BigDecimalVal(bd))
    case dt: LocalDateTime => tokenize(TokenizableValue.DateTimeVal(dt))
    case d: LocalDate    => tokenize(TokenizableValue.DateVal(d))
    case other           => Token(other.toString, TokenType.String, Map("fallback" -> true))
  }
}

object UniversalTokenizer {
  def apply(): UniversalTokenizer = new UniversalTokenizer()
}

// ============================================================================
// Complex Nested Generics
// ============================================================================

/**
 * Registry with complex nested generic types.
 */
final class TokenRegistry[A] {
  private val _registry: mutable.Map[String, TokenContainer[A]] = mutable.Map.empty
  private val _handlers: mutable.ListBuffer[A => Option[Token]] = mutable.ListBuffer.empty

  def register(key: String, container: TokenContainer[A]): Unit =
    _registry(key) = container

  def addHandler(handler: A => Option[Token]): Unit =
    _handlers += handler

  def process(key: String): Seq[Option[Token]] = {
    _registry.get(key) match {
      case None => Seq.empty
      case Some(container) =>
        container.getAll.map { item =>
          _handlers.iterator.map(_(item)).collectFirst { case Some(token) => token }
        }
    }
  }
}

object TokenRegistry {
  def apply[A](): TokenRegistry[A] = new TokenRegistry[A]
}

// ============================================================================
// Functor and Monad Abstractions
// ============================================================================

/**
 * Functor for tokens.
 */
final class TokenFunctor[A](private val _value: A) {

  def map[B](func: A => B): TokenFunctor[B] =
    new TokenFunctor(func(_value))

  def flatMap[B](func: A => TokenFunctor[B]): TokenFunctor[B] =
    func(_value)

  def getOrElse(default: => A): A =
    if (_value != null) _value else default

  def get: A = _value
}

object TokenFunctor {
  def apply[A](value: A): TokenFunctor[A] = new TokenFunctor(value)
}

/**
 * Extended monad operations.
 */
final class TokenMonad[A](private val _value: A) {

  def map[B](func: A => B): TokenMonad[B] =
    new TokenMonad(func(_value))

  def flatMap[B](func: A => TokenMonad[B]): TokenMonad[B] =
    func(_value)

  def getOrElse(default: => A): A =
    if (_value != null) _value else default

  def get: A = _value

  /**
   * Applicative apply.
   */
  def ap[B](funcWrapped: TokenMonad[A => B]): TokenMonad[B] =
    new TokenMonad(funcWrapped._value(_value))
}

object TokenMonad {

  def pure[A](value: A): TokenMonad[A] = new TokenMonad(value)

  def apply[A](value: A): TokenMonad[A] = new TokenMonad(value)
}

// ============================================================================
// JSON Structure Tokenization
// ============================================================================

/**
 * Sealed trait representing JSON values.
 */
sealed trait JsonValue

object JsonValue {
  final case class JsonString(value: String) extends JsonValue
  final case class JsonInt(value: Int) extends JsonValue
  final case class JsonLong(value: Long) extends JsonValue
  final case class JsonDouble(value: Double) extends JsonValue
  final case class JsonBoolean(value: Boolean) extends JsonValue
  case object JsonNull extends JsonValue
  final case class JsonArray(values: Vector[JsonValue]) extends JsonValue
  final case class JsonObject(fields: Map[String, JsonValue]) extends JsonValue

  implicit def fromString(v: String): JsonValue = JsonString(v)
  implicit def fromInt(v: Int): JsonValue = JsonInt(v)
  implicit def fromLong(v: Long): JsonValue = JsonLong(v)
  implicit def fromDouble(v: Double): JsonValue = JsonDouble(v)
  implicit def fromBoolean(v: Boolean): JsonValue = JsonBoolean(v)
}

/**
 * Tokenizer for JSON structures with recursive types.
 */
final class JsonTokenizer(pretty: Boolean = false) {

  def tokenize(value: JsonValue): Token = {
    val jsonStr = if (pretty) toJsonStringPretty(value, 0) else toJsonString(value)
    Token(jsonStr, TokenType.Structured, Map("json" -> true))
  }

  def tokenizePath(value: JsonValue, path: String): Option[Token] = {
    val parts = path.split("\\.").toList
    extractPath(value, parts).map(tokenize)
  }

  private def extractPath(value: JsonValue, parts: List[String]): Option[JsonValue] = parts match {
    case Nil => Some(value)
    case head :: tail =>
      value match {
        case JsonValue.JsonObject(fields) =>
          fields.get(head).flatMap(extractPath(_, tail))
        case JsonValue.JsonArray(values) =>
          Try(head.toInt).toOption.flatMap { idx =>
            if (idx >= 0 && idx < values.length) extractPath(values(idx), tail)
            else None
          }
        case _ => None
      }
  }

  private def toJsonString(value: JsonValue): String = value match {
    case JsonValue.JsonString(s)   => s""""${escapeString(s)}""""
    case JsonValue.JsonInt(i)      => i.toString
    case JsonValue.JsonLong(l)     => l.toString
    case JsonValue.JsonDouble(d)   => d.toString
    case JsonValue.JsonBoolean(b)  => b.toString
    case JsonValue.JsonNull        => "null"
    case JsonValue.JsonArray(arr)  => arr.map(toJsonString).mkString("[", ",", "]")
    case JsonValue.JsonObject(obj) =>
      obj.map { case (k, v) => s""""${escapeString(k)}":${toJsonString(v)}""" }.mkString("{", ",", "}")
  }

  private def toJsonStringPretty(value: JsonValue, indent: Int): String = {
    val spaces = "  " * indent
    val innerSpaces = "  " * (indent + 1)
    value match {
      case JsonValue.JsonString(s)   => s""""${escapeString(s)}""""
      case JsonValue.JsonInt(i)      => i.toString
      case JsonValue.JsonLong(l)     => l.toString
      case JsonValue.JsonDouble(d)   => d.toString
      case JsonValue.JsonBoolean(b)  => b.toString
      case JsonValue.JsonNull        => "null"
      case JsonValue.JsonArray(arr) if arr.isEmpty => "[]"
      case JsonValue.JsonArray(arr) =>
        arr.map(v => innerSpaces + toJsonStringPretty(v, indent + 1)).mkString("[\n", ",\n", s"\n$spaces]")
      case JsonValue.JsonObject(obj) if obj.isEmpty => "{}"
      case JsonValue.JsonObject(obj) =>
        obj.map { case (k, v) =>
          s"""$innerSpaces"${escapeString(k)}": ${toJsonStringPretty(v, indent + 1)}"""
        }.mkString("{\n", ",\n", s"\n$spaces}")
    }
  }

  private def escapeString(s: String): String =
    s.replace("\\", "\\\\")
      .replace("\"", "\\\"")
      .replace("\n", "\\n")
      .replace("\r", "\\r")
      .replace("\t", "\\t")
}

object JsonTokenizer {
  def apply(pretty: Boolean = false): JsonTokenizer = new JsonTokenizer(pretty)
}

// ============================================================================
// Whitespace Tokenizer - Basic Text Tokenization
// ============================================================================

/**
 * Basic tokenizer that splits text by whitespace.
 *
 * This is a fundamental tokenization operation used in NLP and text processing.
 */
final class WhitespaceTokenizer(
    lowercase: Boolean = false,
    minLength: Int = 0,
    maxLength: Option[Int] = None,
    stripPunctuation: Boolean = false
) {

  private val punctuation: Set[Char] = ".,!?;:'\"()[]{}".toSet

  private def processToken(word: String): Option[String] = {
    var processed = word

    if (stripPunctuation) {
      processed = processed.dropWhile(punctuation.contains).reverse.dropWhile(punctuation.contains).reverse
    }

    if (lowercase) {
      processed = processed.toLowerCase
    }

    if (processed.length < minLength) {
      return None
    }

    maxLength.foreach { max =>
      if (processed.length > max) {
        processed = processed.take(max)
      }
    }

    if (processed.isEmpty) None else Some(processed)
  }

  /**
   * Split text by whitespace and return list of tokens.
   */
  def tokenize(text: String): Vector[Token] = {
    val words = text.split("\\s+").filter(_.nonEmpty)
    words.zipWithIndex.flatMap { case (word, i) =>
      processToken(word).map { processed =>
        Token(
          value = processed,
          tokenType = TokenType.String,
          metadata = Map("position" -> i, "original" -> word)
        )
      }
    }.toVector
  }

  /**
   * Split text by whitespace and return list of token strings.
   */
  def tokenizeToStrings(text: String): Vector[String] =
    tokenize(text).map(_.value)

  /**
   * Tokenize text and return tokens with character positions.
   */
  def tokenizeWithPositions(text: String): Vector[(String, Int, Int)] = {
    var currentPos = 0
    val words = text.split("\\s+").filter(_.nonEmpty)

    words.flatMap { word =>
      val start = text.indexOf(word, currentPos)
      val end = start + word.length
      currentPos = end

      processToken(word).map(processed => (processed, start, end))
    }.toVector
  }

  /**
   * Return the number of tokens in the text.
   */
  def countTokens(text: String): Int = tokenize(text).length
}

object WhitespaceTokenizer {
  def apply(
      lowercase: Boolean = false,
      minLength: Int = 0,
      maxLength: Option[Int] = None,
      stripPunctuation: Boolean = false
  ): WhitespaceTokenizer = new WhitespaceTokenizer(lowercase, minLength, maxLength, stripPunctuation)
}

// ============================================================================
// Builder Pattern with Fluent Interface
// ============================================================================

/**
 * Fluent builder for creating tokenizers.
 */
final class TokenizerBuilder[A] private (
    normalizers: Vector[String => String],
    validators: Vector[A => Boolean],
    metadata: Map[String, Any]
) {

  def withNormalizer(normalizer: String => String): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers :+ normalizer, validators, metadata)

  def withValidator(validator: A => Boolean): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators :+ validator, metadata)

  def withMetadata(entries: (String, Any)*): TokenizerBuilder[A] =
    new TokenizerBuilder(normalizers, validators, metadata ++ entries.toMap)

  /**
   * Build the final tokenizer function.
   */
  def build(): A => Either[String, Token] = { (value: A) =>
    val validationErrors = validators.zipWithIndex.collect {
      case (validator, idx) if !validator(value) => s"Validation $idx failed for $value"
    }

    if (validationErrors.nonEmpty) {
      Left(validationErrors.mkString("; "))
    } else {
      var strValue = value.toString
      normalizers.foreach { normalizer =>
        strValue = normalizer(strValue)
      }
      Right(Token(strValue, TokenType.String, metadata))
    }
  }

  /**
   * Build the final tokenizer function that throws on validation failure.
   */
  def buildUnsafe(): A => Token = { (value: A) =>
    build()(value) match {
      case Right(token) => token
      case Left(error)  => throw new IllegalArgumentException(error)
    }
  }
}

object TokenizerBuilder {
  def apply[A](): TokenizerBuilder[A] =
    new TokenizerBuilder(Vector.empty, Vector.empty, Map.empty)
}

// ============================================================================
// Companion functions matching Python module-level functions
// ============================================================================

object Tokenizer {

  /**
   * Convenience function to tokenize a value using UniversalTokenizer.
   */
  def tokenize(value: TokenizableValue): Token =
    UniversalTokenizer().tokenize(value)

  /**
   * Convenience function to tokenize multiple values.
   */
  def tokenizeBatch(values: Iterable[TokenizableValue]): Iterator[Token] =
    values.iterator.map(tokenize)

  /**
   * Convert a Tokenizable value to a Token.
   */
  def toToken[A: Tokenizable](value: A): Token = {
    val tokenString = Tokenizable[A].toToken(value)
    Token(tokenString, TokenType.String)
  }
}

