object Tokenizer {

  /**
   * Convenience function to tokenize a value using UniversalTokenizer.
   */
  def tokenize(value: TokenizableValue): Token =
    UniversalTokenizer().tokenize(value)

  /**
   * Convenience function to tokenize multiple values.
   */
  def tokenizeBatch(values: Iterable[TokenizableValue]): Iterator[Token] =
    values.iterator.map(tokenize)

  /**
   * Convert a Tokenizable value to a Token.
   */
  def toToken[A: Tokenizable](value: A): Token = {
    val tokenString = Tokenizable[A].toToken(value)
    Token(tokenString, TokenType.String)
  }
}

